{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-1/suite-a/tests/TC-01-login.spec.ts","content":"import { test, expect } from './support/fixtures';
import { LoginPage } from '../pages/LoginPage';
import { TopBar } from '../pages/TopBar';

test('TC-01: Login with a valid and an invalid password', async ({ page, customer }) => {
  const loginPage = new LoginPage(page);
  const topBar = new TopBar(page);
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page /#/login', async () => {
    await loginPage.open();
    await expect(loginPage.title).toBeVisible();
    await expect(loginPage.email).toBeVisible();
    await expect(loginPage.password).toBeVisible();
    await expect(loginPage.logInButton).toBeVisible();
  });

  await test.step('2. Log in with the email and the wrong password', async () => {
    await loginPage.logIn(customer.email, wrongPassword);
    await expect(page.getByText('Invalid email or password.')).toBeVisible();
    await expect(page).toHaveURL(/#\/login$/);
  });

  await test.step('3. Open the account menu. It shows Login and not the email', async () => {
    await topBar.openAccountMenu();
    await expect(topBar.menu.getByRole('menuitem', { name: 'Login', exact: true })).toBeVisible();
    await expect(topBar.menu).not.toContainText(customer.email);
  });

  await test.step('4. Close the menu, then log in with the correct password', async () => {
    await topBar.closeMenu();
    await loginPage.logIn(customer.email, customer.password);
    await expect(page).toHaveURL(/#\/search$/);
  });

  await test.step('5. Open the account menu. It shows the email and Logout', async () => {
    await topBar.openAccountMenu();
    await expect(topBar.menu).toContainText(customer.email);
    await expect(topBar.menu.getByRole('menuitem', { name: 'Logout', exact: true })).toBeVisible();
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-1/suite-a/tests/TC-02-add-to-basket.spec.ts","content":"import { test, expect, logIn } from './support/fixtures';
import { PRODUCTS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { TopBar } from '../pages/TopBar';

test('TC-02: Add a product to the basket', async ({ page, customer }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const product = PRODUCTS.eggfruit;

  await logIn(page, customer);

  await test.step('1. Open the product list. The product, its price and Add to Basket are shown. Basket counter is 0', async () => {
    await products.open();
    const card = products.productCard(product);
    await expect(card).toContainText(product);
    await expect(card).toContainText('8.99¤');
    await expect(card.getByRole('button', { name: 'Add to Basket' })).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(0);
  });

  await test.step('2. Click Add to Basket. A message shows and the basket counter is 1', async () => {
    await products.addToBasket(product);
    await topBar.expectSnackBar(`Placed ${product} into basket.`);
    await expect.poll(() => topBar.basketCount()).toBe(1);
  });

  await test.step('3. Open the basket. It has one row with the name, quantity 1 and price 8.99¤', async () => {
    await topBar.openBasket();
    await expect(basket.row(product)).toHaveCount(1);
    await expect(basket.row(product)).toContainText('8.99¤');
    expect(await basket.quantity(product)).toBe(1);
  });

  await test.step('4. The basket shows Total Price: 8.99¤', async () => {
    await expect(basket.totalPrice('8.99¤')).toBeVisible();
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-1/suite-a/tests/TC-03-basket-quantity-and-remove.spec.ts","content":"import { test, expect, logIn } from './support/fixtures';
import { PRODUCTS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { TopBar } from '../pages/TopBar';

test('TC-03: Change the quantity and remove a product in the basket', async ({ page, customer }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const productA = PRODUCTS.raspberry;
  const productB = PRODUCTS.eggfruit;

  await logIn(page, customer);

  // Preconditions: product A and product B, each with quantity 1.
  await products.open();
  await products.addToBasket(productA);
  await topBar.expectSnackBar(`Placed ${productA} into basket.`);
  await products.addToBasket(productB);
  await topBar.expectSnackBar(`Placed ${productB} into basket.`);

  await test.step('1. Open the basket. A: quantity 1, B: quantity 1, Total 13.98¤, counter 2', async () => {
    await topBar.openBasket();
    expect(await basket.quantity(productA)).toBe(1);
    expect(await basket.quantity(productB)).toBe(1);
    await expect(basket.totalPrice('13.98¤')).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(2);
  });

  await test.step('2. Click plus on product A. A: quantity 2, Total 18.97¤, counter 3', async () => {
    await basket.increase(productA);
    await expect.poll(() => basket.quantity(productA)).toBe(2);
    await expect(basket.totalPrice('18.97¤')).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(3);
  });

  await test.step('3. Click minus on product A. A: quantity 1, Total 13.98¤, counter 2', async () => {
    await basket.decrease(productA);
    await expect.poll(() => basket.quantity(productA)).toBe(1);
    await expect(basket.totalPrice('13.98¤')).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(2);
  });

  await test.step('4. Click minus on product A again. A keeps quantity 1 and stays. Total 13.98¤', async () => {
    await basket.decrease(productA);
    await expect(basket.row(productA)).toHaveCount(1);
    expect(await basket.quantity(productA)).toBe(1);
    await expect(basket.totalPrice('13.98¤')).toBeVisible();
  });

  await test.step('5. Click trash on product A. No row for A, B stays with quantity 1, Total 8.99¤, counter 1', async () => {
    await basket.remove(productA);
    await expect(basket.row(productA)).toHaveCount(0);
    expect(await basket.quantity(productB)).toBe(1);
    await expect(basket.totalPrice('8.99¤')).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(1);
  });
});
"}

{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-1/suite-a/tests/TC-04-purchase-limit.spec.ts","content":"import { test, expect, logIn } from './support/fixtures';
import { PRODUCTS } from './support/testData';
import { ProductListPage } from '../pages/ProductListPage';
import { BasketPage } from '../pages/BasketPage';
import { TopBar } from '../pages/TopBar';

test('TC-04: Purchase limit for one product', async ({ page, customer }) => {
  const products = new ProductListPage(page);
  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const product = PRODUCTS.apple;
  const limitMessage = 'You can order only up to 5 items of this product.';

  await logIn(page, customer);

  await test.step('1. Open the product list and add the product. Counter is 1', async () => {
    await products.open();
    await products.addToBasket(product);
    await topBar.expectSnackBar(`Placed ${product} into basket.`);
    await expect.poll(() => topBar.basketCount()).toBe(1);
  });

  await test.step('2. Open the basket and click plus until quantity is 5. Total 9.95¤, no error', async () => {
    await topBar.openBasket();
    for (let quantity = 1; quantity < 5; quantity++) {
      await basket.increase(product);
      await expect.poll(() => basket.quantity(product)).toBe(quantity + 1);
    }
    await expect(basket.totalPrice('9.95¤')).toBeVisible();
    await expect(page.locator('.mat-mdc-snack-bar-container')).toBeHidden();
  });

  await test.step('3. Click plus once more. The error shows', async () => {
    await basket.increase(product);
    await topBar.expectSnackBar(limitMessage);
  });

  await test.step('4. The product keeps quantity 5. Total 9.95¤. Counter is 5', async () => {
    expect(await basket.quantity(product)).toBe(5);
    await expect(basket.totalPrice('9.95¤')).toBeVisible();
    await expect.poll(() => topBar.basketCount()).toBe(5);
  });

  await test.step('5. Open the product list and click Add to Basket. The error shows and counter is 5', async () => {
    await products.open();
    await products.addToBasket(product);
    await topBar.expectSnackBar(limitMessage);
    await expect.poll(() => topBar.basketCount()).toBe(5);
  });
});
"}

