{"file_path":"/Users/arsenvlasov/Documents/WorkFolder/harness-demo-runs/set-3/run-1/suite-a/tests/TC-07-card-order-end-to-end.spec.ts","content":"import { test, expect, logIn } from './support/fixtures';
