  const topBar = new TopBar(page);
  const basket = new BasketPage(page);
  const addressPage = new AddressPage(page);
  const deliveryPage = new DeliveryPage(page);
  const paymentPage = new PaymentPage(page);
  const summary = new OrderSummaryPage(page);
  const completion = new OrderCompletionPage(page);
  const history = new OrderHistoryPage(page);
  const productA = PRODUCTS.eggfruit;
  const productB = PRODUCTS.carrot;

  await logIn(page, customer);
  let orderId = '';

  await test.step('1. Add product A two times and product B one time. Counter is 3', async () => {
    await products.open();
    await products.addToBasket(productA);
    await products.addToBasket(productA);
    await products.addToBasket(productB);
    await expect.poll(() => topBar.basketCount()).toBe(3);
  });

  await test.step('2. Open the basket. A: quantity 2, B: quantity 1, Total 20.97¤', async () => {
    await basket.open();
    expect(await basket.quantity(productA)).toBe(2);
    expect(await basket.quantity(productB)).toBe(1);
    await expect(basket.totalPrice('20.97¤')).toBeVisible();
  });

  await test.step('3. Click Checkout, select the saved address and click Continue', async () => {
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.expectOpen();
  });

  await test.step('4. Select One Day Delivery and click Continue', async () => {
    await deliveryPage.select(DELIVERY.oneDay);
    await deliveryPage.continue();
    await paymentPage.expectOpen();
  });

  await test.step('5. Redeem the coupon of this month. The discount message shows', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(currentMonthCoupon());
    await expect(page.getByText('Your discount of 10% will be applied during checkout.')).toBeVisible();
  });

  await test.step('6. Select the saved card and click Continue. The order summary shows the totals', async () => {
    await paymentPage.selectCard();
    await paymentPage.continue();
    await summary.expectOpen();
    await expect(page.getByText(SAVED_ADDRESS.address).first()).toBeVisible();
    await expect(paymentPage.savedCard()).toBeVisible();
    await expect(summary.line('Items')).toContainText('20.97¤');
    await expect(summary.line('Delivery')).toContainText('0.99¤');
    await expect(summary.line('Promotion')).toContainText('2.10¤');
    await expect(summary.line('Total Price')).toContainText('19.86¤');
