  await logIn(page, customer);
  await products.open();
  await products.addToBasket(product);
  await expect.poll(() => topBar.basketCount()).toBe(1);

  // Opens the basket, then goes through address and delivery to the payment page.
  async function goToPaymentWithStandardDelivery(): Promise<void> {
    await basket.open();
    await basket.checkout();
    await addressPage.select(SAVED_ADDRESS.address);
    await addressPage.continue();
    await deliveryPage.select(DELIVERY.standard);
    await deliveryPage.continue();
