    await addressPage.continue();
    await deliveryPage.expectOpen();
  });

  await test.step('Part 1 / 2. Select Standard Delivery and click Continue. Wallet balance 5.00 and Pay 8.99¤ are shown', async () => {
    await deliveryPage.select(DELIVERY.standard);
